<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";

type Row = Record<string, any>;
const rooms = ref<Row[]>([]); const members = ref<Row[]>([]); const selected = ref<Row | null>(null); const loading = ref(false); const busy = ref(false); const memberLoading = ref(false); const error = ref(""); const message = ref("");
const createDialog = ref(false); const roomForm = ref({ kind: "WATCH", targetType: "RESOURCE", targetId: "", visibility: "INVITE_ONLY", expiresAt: "" }); const inviteForm = ref({ inviteeId: "", role: "MEMBER", expiresAt: "" });
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/rooms"); rooms.value = Array.isArray(result) ? result as Row[] : []; if (selected.value) selected.value = rooms.value.find(row => row.id === selected.value?.id) || null; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "Room 列表加载失败"; } finally { loading.value = false; } }
async function selectRoom(room: Row) { selected.value = room; memberLoading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>(`/rooms/${room.id}/members`); members.value = Array.isArray(result) ? result as Row[] : []; } catch (e: any) { members.value = []; error.value = e?.response?.data?.detail || e?.message || "Room 成员加载失败"; } finally { memberLoading.value = false; } }
function formatDate(value: unknown) { return value ? new Date(String(value)).toLocaleString() : "未设置"; }
async function createRoom() { if (!roomForm.value.kind.trim() || !roomForm.value.targetType.trim() || !roomForm.value.targetId.trim()) { error.value = "请完整填写 Room 类型、目标类型和目标 ID"; return; } busy.value = true; error.value = ""; try { const room: any = await http.post("/rooms", { data: { ...roomForm.value, kind: roomForm.value.kind.trim(), targetType: roomForm.value.targetType.trim(), targetId: roomForm.value.targetId.trim(), expiresAt: roomForm.value.expiresAt ? new Date(roomForm.value.expiresAt).toISOString() : undefined } }); createDialog.value = false; roomForm.value = { kind: "WATCH", targetType: "RESOURCE", targetId: "", visibility: "INVITE_ONLY", expiresAt: "" }; message.value = `Room 已创建，当前状态：${room?.status || "ACTIVE"}`; await load(); const created = rooms.value.find(item => item.id === room?.id) || room; if (created?.id) await selectRoom(created); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "Room 创建失败"; } finally { busy.value = false; } }
async function roomAction(action: string) { if (!selected.value) return; busy.value = true; error.value = ""; try { await http.post(`/rooms/${selected.value.id}/actions/${action}`); message.value = `Room 操作已完成：${action}`; await load(); if (selected.value) await selectRoom(selected.value); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "Room 操作失败"; } finally { busy.value = false; } }
async function joinOrLeave(action: "join" | "leave") { await roomAction(action); }
async function memberAction(member: Row, action: string, role?: string) { if (!selected.value) return; busy.value = true; error.value = ""; try { const suffix = action === "role" ? `?role=${encodeURIComponent(role || "MEMBER")}` : ""; await http.post(`/rooms/${selected.value.id}/members/${member.principalId}/actions/${action}${suffix}`); message.value = "成员状态已更新"; await selectRoom(selected.value); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "成员操作失败"; } finally { busy.value = false; } }
async function invite() { if (!selected.value || !inviteForm.value.inviteeId.trim()) { error.value = "请输入被邀请用户 ID"; return; } busy.value = true; error.value = ""; try { const idempotencyKey = crypto.randomUUID(); await http.post(`/rooms/${selected.value.id}/invites`, { headers: { "Idempotency-Key": idempotencyKey }, data: { inviteeId: inviteForm.value.inviteeId.trim(), role: inviteForm.value.role, idempotencyKey, expiresAt: inviteForm.value.expiresAt ? new Date(inviteForm.value.expiresAt).toISOString() : undefined } }); inviteForm.value = { inviteeId: "", role: "MEMBER", expiresAt: "" }; message.value = "邀请已发送"; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "发送邀请失败"; } finally { busy.value = false; } }
onMounted(load);
</script>
<template>
  <main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">协作 Room</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">通过真实 Room、邀请和成员 API 管理协作房间。</p></div><div class="flex gap-2"><el-button type="primary" @click="createDialog = true">创建 Room</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-alert v-if="message" :title="message" type="success" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 lg:grid-cols-3 gap-5"><el-card shadow="never"><template #header>我的 Room</template><el-skeleton v-if="loading" :rows="5" animated/><el-empty v-else-if="!rooms.length" description="暂无 Room"/><div v-else v-for="room in rooms" :key="room.id" class="p-3 rounded cursor-pointer mb-2" :class="selected?.id === room.id ? 'bg-[var(--el-fill-color-light)]' : ''" @click="selectRoom(room)"><div class="font-medium">{{ room.kind }} · {{ room.targetId }}</div><div class="text-xs mt-1">{{ room.status }} · {{ room.visibility }} · v{{ room.stateVersion }}</div></div></el-card><el-card shadow="never" class="lg:col-span-2"><template #header><div class="flex justify-between items-center"><span>Room 详情</span><span v-if="selected" class="text-sm">{{ selected.id }}</span></div></template><el-empty v-if="!selected" description="选择一个 Room"/><template v-else><div class="flex flex-wrap gap-2 mb-5"><el-tag>{{ selected.status }}</el-tag><el-button :loading="busy" @click="joinOrLeave('join')">加入</el-button><el-button :loading="busy" @click="joinOrLeave('leave')">离开</el-button><el-button v-if="selected.status === 'ACTIVE'" :loading="busy" @click="roomAction('lock')">锁定</el-button><el-button v-if="selected.status === 'LOCKED'" :loading="busy" @click="roomAction('unlock')">解锁</el-button><el-button v-if="selected.status !== 'ENDED'" type="danger" plain :loading="busy" @click="roomAction('end')">关闭 Room</el-button></div><el-divider content-position="left">邀请成员</el-divider><div class="flex flex-wrap gap-2 mb-5"><el-input v-model="inviteForm.inviteeId" placeholder="被邀请用户 ID" class="w-72"/><el-select v-model="inviteForm.role" class="w-32"><el-option label="成员" value="MEMBER"/><el-option label="主持人" value="MODERATOR"/></el-select><el-date-picker v-model="inviteForm.expiresAt" type="datetime" placeholder="邀请过期时间"/><el-button type="primary" :loading="busy" @click="invite">发送邀请</el-button></div><el-divider content-position="left">成员</el-divider><el-skeleton v-if="memberLoading" :rows="4" animated/><el-empty v-else-if="!members.length" description="暂无活跃成员"/><el-table v-else :data="members" stripe><el-table-column prop="principalId" label="用户 ID" min-width="280"/><el-table-column prop="role" label="角色" width="130"/><el-table-column prop="joinedAt" label="加入时间" min-width="180"/><el-table-column label="操作" width="300"><template #default="{ row }"><el-select :model-value="row.role" class="w-32 mr-2" @change="value => memberAction(row, 'role', value)"><el-option label="成员" value="MEMBER"/><el-option label="主持人" value="MODERATOR"/><el-option label="访客" value="GUEST"/></el-select><el-button link type="danger" :disabled="row.role === 'OWNER'" @click="memberAction(row, 'remove')">移除</el-button><el-button link :disabled="row.role === 'OWNER'" @click="memberAction(row, 'transfer-owner')">转移房主</el-button></template></el-table-column></el-table></template></el-card></div><el-dialog v-model="createDialog" title="创建 Room" width="560px"><el-form label-position="top"><el-form-item label="Room 类型" required><el-input v-model="roomForm.kind" placeholder="WATCH / LISTEN"/></el-form-item><el-form-item label="目标类型" required><el-input v-model="roomForm.targetType" placeholder="RESOURCE / QUEUE"/></el-form-item><el-form-item label="目标 ID" required><el-input v-model="roomForm.targetId" clearable/></el-form-item><el-form-item label="可见性"><el-select v-model="roomForm.visibility" class="w-full"><el-option label="仅受邀" value="INVITE_ONLY"/><el-option label="公开" value="PUBLIC"/></el-select></el-form-item><el-form-item label="过期时间"><el-date-picker v-model="roomForm.expiresAt" type="datetime" class="w-full"/></el-form-item></el-form><template #footer><el-button @click="createDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="createRoom">创建</el-button></template></el-dialog></main>
</template>
